INSERT INTO `contract_versions` (`id`, `version`, `title`, `content`, `is_active`, `summary`, `change_notes`, `created_at`, `updated_at`) VALUES
('ebd87b94-e7cb-11f0-b7f8-aee8d4b751de', '1.0', 'Acente Hizmet Sözleşmesi', '<h1>ACENTE HİZMET SÖZLEŞMESİ</h1>\n          <h2>1. TARAFLAR</h2>\n          <p>Bu sözleşme, Şirket ile Acente arasında akdedilmiştir.</p>\n          <h2>2. KONU</h2>\n          <p>Yol yardım hizmet paketlerinin satışına ilişkin koşulları düzenler.</p>\n          <h2>3. ÖNEMLİ UYARI</h2>\n          <p style=\"color:red;font-weight:bold;\">Bu hizmetler SİGORTA ÜRÜNLERİ DEĞİLDİR.</p>\n          <h2>4. YÜRÜRLÜK</h2>\n          <p>Elektronik onay ile yürürlüğe girer.</p>', 1, 'Acente hizmet sözleşmesi', NULL, '2026-01-02 11:12:26', '2026-01-02 11:12:26');
